from pathlib import Path
import json,statistics,hashlib
E=Path(__file__).resolve().parent
b=json.loads((E/'baseline-rows.json').read_text()); c=json.loads((E/'hybrid-rows.json').read_text())
expected=list(range(15))+list(range(3000,3008))
assert [r['trajectory_id'] for r in b]==expected==[r['trajectory_id'] for r in c]
summary={}
for name,seeds in [('Public',range(15)),('development',range(3000,3008))]:
 pairs=[(x,y) for x,y in zip(b,c) if x['trajectory_id'] in seeds]
 deltas=[y['progress']-x['progress'] for x,y in pairs]
 summary[name]={'n':len(pairs),'baseline':statistics.mean(x['progress'] for x,y in pairs),'hybrid':statistics.mean(y['progress'] for x,y in pairs),'delta':statistics.mean(deltas),'gains':sum(d>0 for d in deltas),'ties':sum(d==0 for d in deltas),'losses':sum(d<0 for d in deltas),'baseline_turns_mean':statistics.mean(x['turns'] for x,y in pairs),'hybrid_turns_mean':statistics.mean(y['turns'] for x,y in pairs)}
(E/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Peer depth-20 protection experiment','', 'Request: `20260928T034110788586Z-a8629597f5574a028233d9f49b55a435`.','', 'Complete pinned peer runtime: `github.com/daglar-dragomirov/nethacker@5d0d455a1585271143aa47fbd5b44c2f6dae7d4b`, verified against read-only `/refs/peers/SOURCES.md`. The only runtime difference is the depth >= 20 bypass in `_elbereth_before_digging_escape`. Own influence: `github.com/Xenox-developer/nethacker@7d546b6ab2b972c793489801f609aa691fc82b44`, adapted from the supplied accepted28 diff. Peer license and metadata attribution are preserved. The peer adapter was copied unchanged because its prayer-state handling is part of the requested complete runtime. No incoming-champion policy changes were merged.','', 'Hypothesis: pre-dig engraving at depth >=20 may protect against unseen arrivals. This is a new interaction experiment, not an established combined gain.','', '## Protocol','', '46 fresh games: 23 per arm, Public 0–14 and development 3000–3007. Baseline arm completed before hybrid began. Native arena, public secret, local namespace, val-dwa-law-fem, max_steps 1,000,000, no_progress 10,000, action_timeout 120 seconds, max concurrency 4. Exact commands, elapsed times, raw rows, stdout/stderr, patch and SHA-256 manifests are in `evaluation/peer-depth20/`. No death rerolls, omissions, threshold tuning, or policy changes during evaluation. Development 3000–3007 was already used in attempt29; it is not a holdout.','', '## Fixtures and implementation checks','', 'Both actual helpers imported and passed depth19/20, early Medusa, Weak hunger, intact engraving, polymorph, can_engrave, swallowing, pit rewrite, nearby susceptible monster, sighted cap 4, blind cap 6 despite repeated damage, blind no-new-damage suppression, and unchanged DIG_ESCAPE/Gehennom dispatch fixtures. Only the hybrid depth20 case gained eligibility and called the mock engraving action. ELBERETH_ALWAYS=False and TOOL_RUN_XL=None verified. All other runtime source hashes match the pinned peer.','', 'A pre-evaluation test-only repair replaced list dummy glyphs with an int16 ndarray. Original fixture and error details are retained in `technical-repair.txt` and `fixtures-before-repair.py`. No arena comparison had started; no policy repair was made.','', '## Paired results','', '| Group | Games/arm | Baseline mean | Hybrid mean | Delta | Gains / ties / losses |','| --- | ---: | ---: | ---: | ---: | --- |']
for name,s in summary.items(): lines.append(f"| {name} | {s['n']} | {s['baseline']:.12f} | {s['hybrid']:.12f} | {s['delta']:+.12f} | {s['gains']} / {s['ties']} / {s['losses']} |")
lines+=['','All per-game outcomes, including counterexamples:','','| Group / seed | Baseline | Hybrid | Delta | Baseline turns / hybrid | Baseline death | Hybrid death |','| --- | ---: | ---: | ---: | --- | --- | --- |']
for x,y in zip(b,c):
 seed=x['trajectory_id']; group='Public' if seed<15 else 'development'
 lines.append(f"| {group} {seed} | {x['progress']:.12f} | {y['progress']:.12f} | {y['progress']-x['progress']:+.12f} | {x['turns']} / {y['turns']} | {x.get('cause_of_death')} | {y.get('cause_of_death')} |")
errors=[{'arm':arm,**r} for arm,rows in [('baseline',b),('hybrid',c)] for r in rows if r.get('error') or r['status']!='completed']
(E/'errors.json').write_text(json.dumps(errors,indent=2))
lines+=['','## Activation, uncertainty, and disposition','',f'Arena error/non-completed rows: {len(errors)}; preserved in `errors.json` and the full raw rows. Runtime warnings are preserved in arm logs. No optional counters were added. Real-game helper visits, depth-only eligibility, and resulting engraving actions were not measured. Fixture calls are not evidence of real-game activation. Any apparent gain is low-confidence without actual action evidence; outcome differences alone cannot attribute the mechanism.', '', 'Extra engraving can consume turns and nutrition, delay escape, and fail against Elbereth-immune enemies. Caps remain intact but do not remove these costs. Whole-game turn differences are descriptive, not measurements of engraving overhead. Repeated Public outcomes have varied historically; this is one paired run, not proof of deterministic replication or generalization.', '', 'Attempt28 improved its own Public comparison but tied fresh1081–1083 and did not retest failed21’s1060–1062. The depth restriction is not proven to repair those failures. Attempt29’s prior Public loss and development gain are context only, not reused measurements. The peer author’s Private score is not our result.', '', 'The fully tested hybrid remains in `/workspace` for native outer full Public/publication regardless of this internal comparison. The actual incoming local champion remains the outer parent, preserved read-only in `/refs/parent`; its supplied evaluation is copied separately for provenance. Internal pinned-peer results do not establish improvement over that champion. Native same-run Public and fresh validation remain the only local promotion gates. Outer evaluation, fresh validation, and organizer Private results for this candidate are not yet available; no promotion or publication result is claimed.']
Path('/workspace/PEER_DEEP_PROTECTION_EXPERIMENT.md').write_text('\n'.join(lines)+'\n')
